CREATE DATABASE IF NOT EXISTS product_db CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE product_db;
CREATE TABLE categories (id BINARY(16) NOT NULL, parent_id BINARY(16), name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL, path VARCHAR(2048) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(id), UNIQUE KEY uk_category_slug(slug), KEY ix_category_parent(parent_id), CONSTRAINT fk_category_parent FOREIGN KEY(parent_id) REFERENCES categories(id)) ENGINE=InnoDB;
CREATE TABLE brands (id BINARY(16) NOT NULL, name VARCHAR(160) NOT NULL, slug VARCHAR(180) NOT NULL, PRIMARY KEY(id), UNIQUE KEY uk_brand_name(name), UNIQUE KEY uk_brand_slug(slug)) ENGINE=InnoDB;
CREATE TABLE products (id BINARY(16) NOT NULL, seller_id BINARY(16) NOT NULL, category_id BINARY(16) NOT NULL, brand_id BINARY(16), name VARCHAR(300) NOT NULL, slug VARCHAR(330) NOT NULL, description MEDIUMTEXT, status ENUM('DRAFT','ACTIVE','ARCHIVED') NOT NULL DEFAULT 'DRAFT', version BIGINT NOT NULL DEFAULT 0, created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6) ON UPDATE CURRENT_TIMESTAMP(6), PRIMARY KEY(id), UNIQUE KEY uk_product_slug(slug), KEY ix_product_category_status(category_id,status), KEY ix_product_seller(seller_id), CONSTRAINT fk_product_category FOREIGN KEY(category_id) REFERENCES categories(id), CONSTRAINT fk_product_brand FOREIGN KEY(brand_id) REFERENCES brands(id)) ENGINE=InnoDB;
CREATE TABLE product_variants (id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, sku VARCHAR(100) NOT NULL, title VARCHAR(300), attributes JSON NOT NULL, list_price DECIMAL(19,4) NOT NULL, sale_price DECIMAL(19,4), currency CHAR(3) NOT NULL, weight_grams INT UNSIGNED, active BOOLEAN NOT NULL DEFAULT TRUE, version BIGINT NOT NULL DEFAULT 0, PRIMARY KEY(id), UNIQUE KEY uk_variant_sku(sku), KEY ix_variant_product_active(product_id,active), CONSTRAINT ck_variant_price CHECK(list_price >= 0 AND (sale_price IS NULL OR sale_price >= 0)), CONSTRAINT fk_variant_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE product_images (id BINARY(16) NOT NULL, product_id BINARY(16) NOT NULL, variant_id BINARY(16), url VARCHAR(2048) NOT NULL, alt_text VARCHAR(300), sort_order SMALLINT UNSIGNED NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_image_product(product_id,sort_order), CONSTRAINT fk_image_product FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE CASCADE, CONSTRAINT fk_image_variant FOREIGN KEY(variant_id) REFERENCES product_variants(id) ON DELETE CASCADE) ENGINE=InnoDB;
CREATE TABLE outbox_event (id BINARY(16) NOT NULL, aggregate_type VARCHAR(80) NOT NULL, aggregate_id BINARY(16) NOT NULL, event_type VARCHAR(120) NOT NULL, payload JSON NOT NULL, occurred_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), published_at TIMESTAMP(6), attempts INT NOT NULL DEFAULT 0, PRIMARY KEY(id), KEY ix_outbox_unpublished(published_at,occurred_at)) ENGINE=InnoDB;
